from pathlib import Path
from xml.sax.saxutils import escape
from reportlab.platypus import SimpleDocTemplate, Paragraph, Spacer, PageBreak, Preformatted, KeepTogether
from reportlab.lib.styles import getSampleStyleSheet, ParagraphStyle
from reportlab.lib import colors
from reportlab.lib.enums import TA_LEFT
from reportlab.lib.pagesizes import letter
from pypdf import PdfReader

root = Path(__file__).resolve().parents[1]
output = root / 'Install Guide.pdf'
styles = getSampleStyleSheet()
styles.add(ParagraphStyle(name='TitleSE', fontName='Helvetica-Bold', fontSize=26, leading=29, textColor=colors.HexColor('#123148'), spaceAfter=12))
styles.add(ParagraphStyle(name='SubSE', fontName='Helvetica', fontSize=12, leading=17, textColor=colors.HexColor('#446170'), spaceAfter=12))
styles.add(ParagraphStyle(name='HSE', fontName='Helvetica-Bold', fontSize=12, leading=15, textColor=colors.HexColor('#126C79'), spaceBefore=8, spaceAfter=4))
styles.add(ParagraphStyle(name='BodySE', fontName='Helvetica', fontSize=9.3, leading=12, spaceAfter=5))
styles.add(ParagraphStyle(name='SmallSE', fontName='Helvetica', fontSize=8.5, leading=11, textColor=colors.HexColor('#446170'), spaceAfter=7))
styles.add(ParagraphStyle(name='CodeSE', fontName='Courier-Bold', fontSize=8.5, leading=11, backColor=colors.HexColor('#F0F4F6'), borderPadding=7, spaceBefore=4, spaceAfter=9))
story=[]
def p(text,style='BodySE'):
    story.append(Paragraph(text,styles[style]))
def h(text): p(text,'HSE')
def code(text): story.append(Preformatted(escape(text),styles['CodeSE']))
def page(title,subtitle):
    p(title,'TitleSE'); p(subtitle,'SubSE')
def link(label,url):
    p(f'<link href="{url}" color="#126C79"><u>{label}</u></link>','SmallSE')

page('Install guide','Signal Explorer | Windows source installation<br/>Version 0.1.0 - DBC editor and adapter preferences<br/>Document revision 1.4 - October 31, 2026')
p('This guide installs the current Python desktop application on another PC. A standalone installer will be addressed later. You need internet access for the initial Python package downloads and any required driver downloads.')
h('1. Prepare the PC and project files')
p('Install <b>64-bit Python 3.12</b> and its Python launcher. This is the version used on the development PC. The project declares Python 3.11 or later, but other versions have not been validated here.')
p('Copy or clone the project into a writable folder, for example <b>C:\\Tools\\Signal Explorer</b>. Include <b>pyproject.toml</b>, <b>README.md</b>, and the complete <b>src</b> folder. Copy <b>examples</b> for the demo DBC and <b>tests</b> if you want to run checks. Do not copy the old <b>.venv</b>; create one on the new PC. Git is optional if you copy the files.')
p('Keep the complete src/signal_explorer/assets and scripting folders: the package includes the SE window icon, startup splash and built-in demo script. Copy examples/scripts/mcu for the companion scripting tutorials. No additional runtime package is required for File Viewer or the Python runner.','SmallSE')
h('2. Install the application')
p('Open PowerShell in the project root - the folder containing pyproject.toml - and run:')
code('cd "C:\\Tools\\Signal Explorer"\npy -3.12 -m venv .venv\n.\\.venv\\Scripts\\python.exe -m pip install .')
p('Using the virtual environment executable directly avoids the need to activate it or change PowerShell script-execution settings.')
h('3. Launch Signal Explorer')
code('.\\.venv\\Scripts\\python.exe -m signal_explorer')
p('Run this command from the project root whenever you want to start the application. SignalExplorer.bat resolves its own folder and launches that folder\'s .venv interpreter; it does not require activation or a hard-coded PC path.','SmallSE')
h('Packages installed automatically')
p('<b>PySide6-Essentials</b> - desktop UI; <b>python-can</b> - CAN interfaces; <b>pyserial</b> - serial adapters; <b>cantools</b> - DBC decoding; <b>ldfparser</b> - LIN descriptions; <b>uptime</b> - timestamp support; <b>asammdf</b> via python-can[mf4] - ASAM MDF4 recording and playback. pip also installs dependencies such as NumPy and pandas. Build tooling includes setuptools. These are application dependencies, separate from vendor hardware drivers.')

story.append(PageBreak())
page('Adapter requirements','Install only the software needed for the adapters you plan to use.')
p('Install vendor-supplied drivers/APIs matching this 64-bit installation before connecting hardware, unless the installer requests USB connection. Keep bus wiring disconnected during setup. Driver installers may need administrator approval. Vendor DLLs are not included in the source.')
h('Virtual CAN, LIN and Ethernet - no hardware')
p('No vendor software is required for the simulators. Choose a virtual adapter in the relevant tab; demo traffic/peers let you test monitoring, sending and logging without physical bus traffic.')
h('CANable - SLCAN firmware')
p('Windows must recognize the adapter as a serial COM port. Install its appropriate USB serial driver if Windows does not configure it automatically. No additional Python packages are required. Choose CANable (SLCAN serial), select its actual COM port, and match the CAN bus bitrate. The new PC may assign a port other than COM3.')
h('CANable - candleLight / gs_usb firmware')
p('This is a different USB connection path from SLCAN. Install the additional backend:')
code('.\\.venv\\Scripts\\python.exe -m pip install "python-can[gs-usb]"')
p('A compatible USB driver and libusb backend may also be needed on Windows. Configure those for the device\'s firmware, then choose CANable / candleLight (gs_usb). This path has not been physically validated in this project; the tested CANable connection is SLCAN.')
h('Vector - VN16xx / CANXL adapter option')
p('Install Vector hardware drivers <b>and the 64-bit XL Driver Library</b>. The USB driver alone is insufficient. Signal Explorer checks PATH and the standard Public Documents/Vector/XL Driver Library*/bin folder. If detection fails, use <b>Vector DLL</b> to select the installed <b>vxlapi64.dll</b>, then restart. Select the detected serial number and physical CAN channel; no application assignment in Vector Hardware Config is required.')
link('Vector XL Driver Library', 'https://www.vector.com/en/business-unit/testing-validation-diagnostics/products/network-interfaces/xl-driver-library/')
h('Kvaser - including U100-C')
p('Install Kvaser Windows drivers with the CANlib runtime. Select Kvaser (U100 / CANlib), then Refresh devices. Channel indices start at zero. A listed Kvaser virtual channel is not a physical U100-C.')
h('PEAK - including PCAN-USB Pro FD')
p('Install PEAK hardware drivers and the 64-bit <b>PCAN-Basic API</b> (PCANBasic.dll). Select the PEAK option and a detected CAN channel. Manual names include PCAN_USBBUS1 and PCAN_USBBUS2; use detected names when several adapters are attached.')
p('For <b>LIN</b>, separately install PEAK LIN drivers, <b>PLIN Manager</b> and 64-bit <b>PLIN-API</b> (PLinApi.dll). PCAN-Basic alone does not supply LIN. Select LIN &gt; PEAK PLIN / PCAN-USB Pro FD, Refresh, then a detected LIN channel. PCAN-USB Pro/Pro FD and PLIN-USB families use this API; a CAN-only PCAN-USB cannot supply LIN. Native PEAK LIN is experimental and awaits a physical bench test.')
h('Intrepid - ValueCAN / neoVI')
p('Install Intrepid hardware drivers and its native 64-bit <b>icsneo40.dll</b>, then install the optional Python dependencies:')
code('.\\.venv\\Scripts\\python.exe -m pip install ".[intrepid]"')
p('This adds python-ics and filelock. Select the Intrepid adapter by serial number, not its COM port. For ValueCAN4-2, HSCAN is CAN1 and HSCAN2 is CAN2.')

story.append(PageBreak())
page('Verify and troubleshoot','A short check before connecting to a live CAN bus.')
h('1. Verify the software without hardware')
p('Launch Signal Explorer, select <b>Virtual</b>, enable <b>Inject demo traffic</b>, and click <b>Connect</b>. The trace should show ID 100 with changing data. Load <b>examples/demo.dbc</b> to display the demo message name and decoded signals.')
p('Auto-scroll (all messages) is checked by default and shows timestamped history. Uncheck it for the latest data per channel and ID. History retains the most recent 10,000 frames. <b>Pause Exploring</b> freezes trace updates while staying connected; <b>Start Exploring</b> resumes. Frames received while paused are not replayed.')
h('2. Verify hardware reception')
p('Connect the adapter by USB, choose its backend and channel, set the correct bus bitrate, and click Connect. Use a powered, correctly wired and terminated CAN bus with a device that is transmitting. Check the RX count. Click Clear filter if frames might be hidden. Merely connecting USB does not generate CAN traffic.')
h('Common issues')
p('<b>Python or py is not recognized:</b> verify Python 3.12 is installed and reopen PowerShell. Check with <b>py -3.12 --version</b>.')
p('<b>No module named signal_explorer:</b> run the install command from the project root and launch using the same .venv Python executable.')
p('<b>COM port access denied:</b> disconnect that port in other Signal Explorer windows and close other programs using it. Only one process can hold the CANable serial port.')
p('<b>Connected, RX stays at zero:</b> confirm the bus has traffic, the bitrate matches, CAN-H/CAN-L wiring is correct, and the required termination is present. A quiet bus can connect successfully without producing trace rows.')
p('<b>RX increases but the trace appears empty:</b> click Clear filter and ensure exploring is running. While paused, trace counters and rows stay frozen.')
p('<b>Missing DLL or no detected channels:</b> install the vendor\'s 64-bit API as well as its USB driver. Reconnect USB, use Refresh devices, or restart after changing DLL settings. No attached device can legitimately produce an empty channel list.')
h('Optional automated checks')
p('For optional checks, copy tests and install the test dependencies with pip install ".[dev,intrepid]" in this .venv. From the project root run:')
code('.\\.venv\\Scripts\\python.exe -m pytest tests -q')
p('166 automated checks pass, including adapter preferences, DBC editing and NI-XNET mocks. USB-8502 traffic, Ethernet TX and powered ValueCAN LIN/Ethernet await bench tests.','SmallSE')
h('Logging and playback')
p('Click <b>Start Logging</b> to record RX and TX; <b>Stop Logging</b> finalizes the MDF4 file and opens a save dialog. Cancelling retains it for <b>Save Log...</b>. Logging continues while the trace is paused or filtered. <b>Playback Log as TX</b> replays a selected recorded bus/direction at best-effort 1x timing through the connected adapter; <b>Stop Playback</b> stops it. Physical timing and third-party interoperability are not yet qualified.')
h('Current scope')
p('CAN supports Classic/FD. LIN offers simulated Monitor/Master/Slave and experimental native Intrepid, Vector XL and PEAK PLIN. Ethernet now offers an isolated simulator, Windows PC Ethernet through Npcap, and ValueCAN4-2EL Ethernet. Sending, repeat, filters and MF4/replay are available. Ethernet setup is on pages 5-6. SENT, CAN XL and a packaged installer remain future work.')
p('DBC files are optional; copy the files you intend to use separately. No compiler is normally needed when compatible prebuilt Python wheels are available. Record working package versions for reproducible deployments; the current project uses minimum version constraints rather than a pinned dependency lock.','SmallSE')

story.append(PageBreak())
page('LIN adapter setup','Monitor, Master and Slave | native drivers are experimental until bench validation.')
h('Intrepid ValueCAN4-2EL')
p('Install the Intrepid drivers, 64-bit <b>icsneo40.dll</b>, and the optional Python dependencies shown on page 2. In the LIN tab select <b>Intrepid ValueCAN4-2EL</b>, Refresh, then its serial number and LIN 1. The app checks the actual device type: ValueCAN4-2 and ValueCAN3 are CAN-only and will not appear here. The development unit VE0245 was detected and its settings read over USB; physical LIN traffic has not been tested.')
p('Baud rate and the master resistor are configured for the selected role through temporary settings, with no EEPROM writes. Disconnect restores the saved settings and closes the native handle, leaving LIN communication off until a new session enables it. <b>Wake is disabled for Intrepid</b> because its legacy Python binding has no verified dedicated wake-pulse operation; use the external master to wake a sleeping bus.')
h('Vector VN1640 with LIN piggies')
p('Use the installed Vector hardware drivers and XL Driver Library from page 2. In LIN select <b>Vector VN16xx / XL LIN</b> and Refresh. Select the serial, physical LIN channel and piggy shown by the driver. The VN1640 requires LIN piggies installed and configured. A VN1610 with CAN transceivers is not a LIN interface. Release initialization access in CANalyzer or other XL applications before connecting this channel.')
h('PEAK PLIN')
p('Install PEAK LIN drivers, PLIN Manager and the matching 64-bit PLIN-API as described on page 2. Select <b>PEAK PLIN / PCAN-USB Pro FD</b> and Refresh. PCAN-Basic is the separate CAN API; it does not provide LIN. Close other PLIN clients on the selected LIN channel.')
h('Choose a role and transmit')
p('<b>Monitor:</b> no local responses or header requests. <b>Master:</b> Send Header requests one defined ID; Start Schedule cycles the configured slots. Selected local response data can be transmitted with the header. <b>Slave:</b> select local publishers and Apply Responses; the adapter waits for the external master header before responding. Response updates are buffered in hardware, not generated from a GUI callback.')
p('Load the matching LDF, baud rate, frame lengths and checksum model on both nodes. Pause Exploring freezes only the trace; stop the schedule or playback separately. Start Logging records RX/TX independently of trace filters. Master playback replays headers with current response configuration; Slave playback updates the selected response buffers at recorded times.')
h('Device ownership and powered bench check')
p('Signal Explorer prevents concurrent CAN/LIN on the same Vector and CAN/LIN/Ethernet on the <b>same Intrepid device</b>. Disconnect that device\'s existing session first. Different devices may remain connected in separate tabs; shared native multi-protocol sessions are future work.')
p('USB alone is sufficient for detection, not a powered LIN bus test. Follow the vendor connector pinout, supply requirements and common-ground wiring, with exactly one master and the proper LIN master pull-up. LIN does not use CAN termination. Verify responder removal, RX/TX direction, checksum/error reporting, timing, sleep/wake and MF4 import on the real bench. Mock tests cannot qualify these physical behaviors.')

story.append(PageBreak())
page('Ethernet adapter setup','PC Ethernet through Npcap | Intrepid ValueCAN4-2EL | simulation stays available')
h('1. Install PC Ethernet capture support')
p('Install current <b>Npcap</b> from its official installer. This is a separate Windows driver/runtime, not a Python package and not bundled with Signal Explorer. The app loads <b>%SystemRoot%\\System32\\Npcap\\wpcap.dll</b>; it does not use a DLL copied into the project. No Scapy or additional Python capture package is required.')
link('Npcap download and installation instructions','https://npcap.com/guide/npcap-users-guide.html')
p('Follow your Npcap capture-permissions policy. If installed with administrator-only access, opening an adapter may require an elevated app session. Normal capture permissions otherwise suffice. Raw Wi-Fi/monitor-mode support is not needed for this release: Wi-Fi and loopback are not offered. The app does not change PC IP addresses, link speeds or duplex.')
h('2. Install ValueCAN4-2EL support')
p('Use the same Intrepid Windows driver, matching 64-bit <b>icsneo40.dll</b>, and optional packages as CAN/LIN. On the new PC run:')
code('.\\.venv\\Scripts\\python.exe -m pip install ".[intrepid]"')
p('Use current python-ics with the vendor\'s Ethernet buffer fixes (1!26.3.9+ recommended; this build used 1!26.3.17). Copying the project does not copy installed native drivers. Select the actual ValueCAN4-2EL serial; CAN-only ValueCAN4-2 and ValueCAN3 are not Ethernet adapters.')
p('Provide the vendor-specified <b>external 12 V</b> and matching Ethernet breakout cable. USB detection alone is insufficient for Ethernet. The 2EL has a 10/100 PHY; preserve/configure its speed/duplex in neoVI Explorer, then release that tool before app connection. Signal Explorer enables Ethernet temporarily in RAM, restores settings on close and never writes EEPROM.')
link('ValueCAN4-2EL power and Ethernet specifications','https://intrepidcs.com/products/vehicle-network-adapters/valuecan-4/valuecan-4-2el-specifications/')
h('3. Discover and select')
p('Open <b>Ethernet</b>: first display scans adapters. <b>Refresh adapters</b> rescans while disconnected. The list always keeps <b>Simulated Ethernet</b>, plus detected PC Ethernet interfaces and 2EL units. PC entries show name, MAC and up/down state; virtual Ethernet interfaces are included. Interfaces can remain listed but disabled when Npcap/capture access is unavailable.')
p('Select the intended port and Connect Ethernet to start capture. Discovery itself never opens a session or transmits. Optional <b>Promiscuous capture</b> applies only to PC ports; a switch mirror/TAP is needed to observe other switch ports. Disconnect CAN/LIN sessions on the same ValueCAN before opening its Ethernet session.')
h('4. Check setup without transmission')
p('Use a known transmitting peer to confirm passive RX and link state. Clear filters and Start Exploring if needed. Simulation needs no driver: select it, enable demo traffic/peer, connect and inspect test frames. Demo traffic and synthetic ACK replies stay inside the simulator; they never run on hardware.')

story.append(PageBreak())
page('Ethernet verification & recovery','Confirm the selected interface and expected traffic before sending or replaying.')
h('Simulation acceptance check')
p('Choose Simulated Ethernet and Connect Ethernet with demo traffic and peer enabled. Expect UDP telemetry, ARP, VLAN UDP and raw 88B5 test frames. Select VLAN UDP, Load Test Frame and Send once: expect local TX and a synthetic ACK RX. Enter 100 in Interval (ms) to repeat; Send becomes Stop. Inject Test RX is simulation-only.')
h('Hardware capture and controlled transmit check')
p('Choose the exact PC port or externally powered 2EL and Connect Ethernet. A session-open status is not proof of physical link. Verify peer traffic first. Load/edit a suitable test frame, including destination MAC and payload for the bench, then Send once and confirm bytes at the independent peer before repeat/playback. Physical TX acceptance remains pending for this build.')
p('PC test presets use the selected NIC source MAC; their IP/destination values remain example addresses. ValueCAN raw frames use the editor source MAC. No automatic ARP resolution, TCP session, DoIP activation line, DoIP/XCP stack or PC IP configuration is provided. Hardware Send/repeat/playback cause real transmission on the selected port.')
h('Logging and playback')
p('Start Logging records RX/TX before display filters/pause; Stop Logging prompts for an .mf4 name. Cancel retains it for Save Log.... Playback Log as TX, or Playback Log as Simulated TX on the virtual adapter, selects recorded bus/direction and replays at best-effort 1x timing. Playback stops repeated sending. Old Ethernet simulation logs still work; unrelated CAN/LIN logs do not.')
p('Ethernet stores raw frames in an MDF 4.10 container using custom <b>SignalExplorer_EthernetFrame</b> records. It is not standardized ASAM Ethernet bus-event interchange or independent conformance certification. TX means driver/API acceptance, not peer receipt. FCS is excluded, while NIC-provided padding may be absent and is added when replay requires minimum TX length.')
h('Common Ethernet issues')
p('<b>Capture unavailable:</b> install/check Npcap and permissions; Refresh adapters. <b>No ports:</b> check Windows device enumeration; Wi-Fi/loopback are intentionally excluded. <b>ValueCAN in use:</b> release other CAN/LIN/Vehicle Spy/neoVI sessions on that serial.')
p('<b>No RX:</b> verify cable/link and peer traffic; 2EL also needs 12 V. An ordinary switched port does not see every other port. <b>Checksum warning:</b> raw packet edits or NIC checksum offload can be responsible; verify at a peer before blaming the bus.')
p('<b>Driver drops:</b> Npcap capture/interface loss; Intrepid shows n/a. <b>Display drops:</b> UI queue overflow, separately from recorder overflow. <b>Unsupported/error frames:</b> rejected captures, not logged; includes jumbo/truncated/stacked-VLAN/802.3 length frames or native CRC/length faults. Standard MTU 1500 and one VLAN tag are supported.')
p('No sustained line-rate or lossless capture guarantee is claimed. Native RX/API failures close the session and stop/finalize active operations. Use the full users guide for column definitions, controls, recovery and cable-specific CAN/LIN/Ethernet pinouts.','SmallSE')

story.append(PageBreak())
page('October 29 update & File Viewer','Revision 1.2 | Python scripting, log viewing and timestamp correction')
h('1. Update an existing source installation')
p('Close Signal Explorer and its editor/viewer windows, preserving any unsaved scripts and logs. Replace/update the project files. From the project root, reinstall into the same environment:')
code('.\\.venv\\Scripts\\python.exe -m pip install .\n# Intrepid users instead use:\n.\\.venv\\Scripts\\python.exe -m pip install ".[intrepid]"')
p('For an editable development installation use -e . or -e ".[intrepid]". Launch with the same .venv interpreter. Do not run a new GUI alongside an older process holding the adapter. The Python worker uses the application\'s interpreter; there is no separate scripting executable to install.')
h('2. Confirm startup branding and the menu')
p('The black SE icon has a red S and white E. A separate splash adds white SIGNAL above the mark and EXPLORER below it. It appears during imports/window construction and closes when the main application opens. File Viewer replaces the former Scripts menu; the title-bar icon remains the SE mark.')
h('3. Verify scripting without hardware')
p('Connect Virtual CAN with Inject demo traffic checked. Choose File Viewer &gt; Open CAN Simulation Example and Run. The script sends ID 321 hex with eight bytes; the virtual peer replies on 221 hex with the same bytes. Each verified exchange increments every byte, wraps FF to 00 and repeats until Stop. Pause/Resume/Stop and Script Output are in the separate editor. CAN FD mode also supports the eight-byte echo.')
p('Use File Viewer &gt; Open Python Script... for examples/scripts/mcu/*.py. Five examples use the built-in simulator. The other four require matching MCU firmware and default to a configuration guard before TX. Read Scripting User\'s Guide.pdf before adapting them. The se context is injected by the app; it is not a pip package.','SmallSE')
h('4. Verify log viewing and replay')
p('Use File Viewer &gt; Open Logfile for a single-protocol CAN/CAN FD, LIN or Signal Explorer Ethernet MF4. Logs open read-only, even offline. Connect the corresponding destination, select Recorded bus and RX only/TX only/RX and TX, then Replay. Pause/Resume/Stop, highlighted rows, Follow execution and Replay Output remain in the viewer. Log line delay changes display refresh only, preserving 1x transmission timing; Python line delay slows actual script execution.')
h('5. Make fresh Intrepid recordings after this update')
p('The app now anchors Intrepid CAN/LIN/Ethernet RX hardware intervals to host time per connection, aligning them with local TX. Earlier recordings could mix a 2007 device-clock epoch with the PC clock and flatten subsequent timestamps. Their original timing cannot be recovered. Restart, reconnect and record a new file. Replay detects selected gaps over 24 hours before any TX and bounds platform waits to prevent timeout overflow. No Skip gaps control is provided.')
h('Runtime versus documentation tooling')
p('The tutorials use only Python\'s standard library and the existing app CAN API. No CAPL compiler, external editor, UDS library or CAN transport package is added. Full UDS/ISO-TP, LIN/Ethernet scripting and a standalone installer remain future work. reportlab and pypdf are needed only to regenerate the manuals, not to run Signal Explorer.','SmallSE')

story.append(PageBreak())
page('NI-XNET / USB-8502 setup','October 30, 2026 | One-port and two-port high-speed CAN / CAN FD')
h('1. Install the NI software before USB connection')
p('Use Windows x64 and the application\'s 64-bit Python environment. Obtain NI-XNET for your Windows version and USB-8502 from NI. Include NI Measurement &amp; Automation Explorer (MAX), follow the installer\'s connection prompts and restart if requested. The native driver is separate from the Python binding. NI-CAN, NI-DAQmx and LabVIEW are not needed for this backend.')
link('NI-XNET driver download','https://www.ni.com/en/support/downloads/drivers/download.ni-xnet.html')
h('2. Add the optional Python binding')
p('Close Signal Explorer. From the project root, install the NI extra using the interpreter that launches the app:')
code('.\\.venv\\Scripts\\python.exe -m pip install ".[nixnet]"\n# To include both optional vendor bindings:\n.\\.venv\\Scripts\\python.exe -m pip install ".[intrepid,nixnet]"')
p('Use -e before the quoted package selector for editable development. Installing the binding does not install the NI-XNET Windows driver. Other adapters remain available without this optional extra.','SmallSE')
h('3. Verify the adapter and select the correct port')
p('Connect USB; the USB-8502 does not need external power for CAN. Locate it in NI MAX and note each CAN interface name (for example CAN1 or CAN2) and physical port. Use MAX Bus Monitor with a known-good peer and matching rates to verify RX; close that monitor and other sessions before opening this port in Signal Explorer.')
p('In the CAN tab choose <b>NI (USB-8502 / NI-XNET)</b>, then <b>Refresh devices</b>. Select the detected model/serial/interface/port, or enter the exact NI MAX CAN name manually. Start with Classic CAN and a matching bitrate. <b>NI internal termination (120 ohm)</b> defaults off; enable only if this port needs an end resistor. It cannot be changed while connected.')
h('4. Confirm Classic CAN, then CAN FD')
p('Connect and check a known RX ID. Send eight known bytes and confirm them independently at the peer; local TX only confirms API acceptance. For FD, disconnect, enable CAN FD and match arbitration/data rates, reconnect, then select FD frame and BRS. Start with 500 kbit/s arbitration and 2 Mbit/s data if the peer supports them. USB-8502 revisions with TJA1043T are certified for FD data up to 5 Mbit/s; 8 Mbit/s is experimental. Verify your hardware revision.')
p('The normal CAN trace, filters, DBC, repeat send, Python scripts, MF4 RX/TX recording and timed replay use this connection. First confirm bytes and timing at the peer. This release has mock coverage for NI enumeration, native frame conversion and MF4 recording; physical USB-8502 qualification remains pending.','SmallSE')
h('Troubleshooting and scope')
p('<b>Python API unavailable:</b> install .[nixnet] in this .venv. <b>Scan/DLL error:</b> install or repair 64-bit NI-XNET. <b>No channels:</b> check USB and NI MAX; Refresh. <b>Connect/rate failure:</b> check the exact CAN name, peer rates and competing sessions. <b>Bus-off:</b> stop TX, repair wiring/termination/peer ACK, then disconnect/reconnect.')
p('USB-8473 / NI-CAN is excluded. Only high-speed/FD NI interfaces are enumerated; other NI-XNET models require separate qualification. No NI LIN, Ethernet or synchronization controls are added. See the updated User\'s Guide for the NI electrical profile, pinout revision differences and detailed bench checks.','SmallSE')
link('NI Python requirements and installation','https://nixnet.readthedocs.io/en/stable/installation.html')

story.append(PageBreak())
page('DBC editor & adapter defaults','October 31, 2026 | Source update and offline verification')
h('1. Update the existing installation')
p('Close Signal Explorer, preserving unsaved scripts, DBC changes and logs. Update the source and reinstall from the project root with the same .venv interpreter. The DBC editor uses the existing Qt and cantools packages; no new runtime dependency, external editor, license server or vendor driver is required for offline editing.')
code('.\\.venv\\Scripts\\python.exe -m pip install .\n# Preserve both optional vendor integrations when needed:\n.\\.venv\\Scripts\\python.exe -m pip install ".[intrepid,nixnet]"')
p('Use -e before the package selector for an editable development install. Keep the complete src/signal_explorer/dbc and ui folders when copying source. The companion Scripting User\'s Guide is unchanged by this release.','SmallSE')
h('2. Adapter selection on launch')
p('Adapter dropdowns are alphabetical in CAN, LIN and Ethernet. On the first run of each protocol, the virtual adapter is selected even if hardware is connected. Later launches remember that protocol\'s last selected adapter for this Windows user profile. CAN/LIN remember the backend family; Ethernet remembers the NIC/device identity, not its list index.')
p('Restoring a selection never connects automatically. Use Refresh to discover current hardware and select the channel and bus parameters before Connect. If the saved Ethernet device is missing or unavailable, the app selects Virtual while retaining the saved identity for a later Refresh. These preferences are local Qt settings, separate from the project and .venv; copying the project to another PC does not copy them.')
h('3. Confirm the DBC editor without hardware')
p('On the CAN screen load examples/demo.dbc, then click Edit DBC. A separate window should show messages, signals, a payload bit map, generated DBC preview and Test decoding. Double-click a message/signal to view its properties; Validate checks the database. Use New to create a blank database, or Open to edit another file.')
p('For a self-contained test, add an eight-byte standard Classic CAN message, ID 321 hex. Add EngineRPM at start bit 0, length 16, Intel unsigned, factor 0.25, offset 0 and unit rpm. In Test decoding enter 40 1F 00 00 00 00 00 00; expect 2000 rpm. This offline test sends no CAN frame.')
h('4. Check save and decoder behavior')
p('Save As to a temporary .dbc file and reopen it to confirm its definitions. Unsaved edits remain private. Save to the exact file currently loaded on the CAN screen reloads its decoder; Save As to another path does not select that new file for live decoding. Use Load DBC to activate it explicitly. Closing/New/Open prompt to save dirty work; Cancel keeps the editor open.')
h('Limits and recovery')
p('Invalid or overlapping/out-of-payload signals are rejected. Use Undo/Redo for accepted edits. Test decoding needs exactly the selected message\'s byte length. Motorola uses DBC sawtooth start-bit numbering; do not assume Intel positions. Multiplexing/float definitions are preserved but not configured by the basic forms. Text must fit Windows-1252; serialization can change formatting. The editor does not encode/transmit signal values.')
p('The User\'s Guide contains the complete editor control map and practical workflow. docs/dbc-editor.md describes its save isolation and module boundaries. Physical adapter qualification is unchanged.','SmallSE')

def decorate(canvas,doc):
    w,h=letter
    canvas.setStrokeColor(colors.HexColor('#126C79'))
    canvas.setLineWidth(2)
    canvas.line(43,h-29,w-43,h-29)
    canvas.setFont('Helvetica',8)
    canvas.setFillColor(colors.HexColor('#446170'))
    canvas.drawString(43,25,'SIGNAL EXPLORER  /  INSTALL GUIDE  /  REV 1.4  /  OCT 31, 2026')
    canvas.drawRightString(w-43,25,str(doc.page))

doc=SimpleDocTemplate(str(output),pagesize=letter,rightMargin=43,leftMargin=43,topMargin=46,bottomMargin=43,title='Install guide - Signal Explorer',author='Signal Explorer')
doc.build(story,onFirstPage=decorate,onLaterPages=decorate)
r=PdfReader(str(output))
print('Created:',output)
print('Pages:',len(r.pages))
for i,page in enumerate(r.pages,1):
    text=page.extract_text()
    print(i, len(text),text[:60].replace('\n',' '))
assert len(r.pages)==9, 'Unexpected pagination; inspect layout'
